<?= $this->extend('layouts/main') ?>
<?= $this->section('content') ?>
<section class="wrap products-section"><h1>Your cart</h1>
<?php if (session('error')): ?><p role="alert"><?= esc(session('error')) ?></p><?php endif ?>
<?php if (session('success')): ?><p role="status"><?= esc(session('success')) ?></p><?php endif ?>
<?php if (! $items): ?><p>Your cart is empty.</p><a class="button button-dark" href="<?= site_url('catalog') ?>">Explore products</a><?php else: ?>
<?php foreach ($items as $item): ?><article class="cart-item"><div><h2><?= esc($item['name']) ?></h2><p><?= format_rupiah((string) $item['price']) ?> each</p><p>Subtotal: <?= isset($item['line_total']) ? format_rupiah(cents_to_money($item['line_total'])) : 'Amount too large' ?></p><?php if ($item['price_at_add'] === null || money_to_cents((string) $item['price_at_add']) !== money_to_cents((string) $item['price'])): ?><p role="alert">Price changed. Review the current price and select Update to accept it.</p><?php endif ?><?php if (! $item['category_active'] || $item['status'] !== 'active' || (int) $item['quantity'] > (int) $item['stock']): ?><p role="alert">This item is unavailable in the requested quantity. Please update your cart.</p><?php endif ?></div><form method="post" action="<?= site_url('cart/items/' . $item['id'] . '/update') ?>"><?= csrf_field() ?><label for="qty-<?= esc($item['id']) ?>">Quantity</label><input id="qty-<?= esc($item['id']) ?>" name="quantity" type="number" min="1" value="<?= esc($item['quantity']) ?>" required><button type="submit">Update</button></form><form method="post" action="<?= site_url('cart/items/' . $item['id'] . '/delete') ?>"><?= csrf_field() ?><button type="submit">Remove</button></form></article><?php endforeach ?><p><strong>Total: <?= $subtotal === null ? 'Amount too large' : format_rupiah(cents_to_money($subtotal)) ?></strong></p><p><a class="button button-dark" href="<?= site_url('checkout') ?>">Continue to checkout</a></p><?php endif ?></section>
<?= $this->endSection() ?>
